-- Minimal seed data for MVP
-- Safe to run multiple times thanks to slug-based upserts.
-- Dish photos: Wikimedia Commons (commons.wikimedia.org) — see each file page for license and attribution; illustrative for MVP.
-- Each run deletes and re-inserts public.dishes so photo URLs stay current (MVP seed only).
-- Must-eat count: 8 per pilot city (within 5–12); 1 hidden gem per city.

-- Cities
insert into public.cities (slug, name, country, region)
values
  ('tokyo', 'Tokyo', 'Japan', 'Kanto'),

  ('paris', 'Paris', 'France', 'Île-de-France'),

  ('mexico-city', 'Mexico City', 'Mexico', 'CDMX'),

  ('bangkok', 'Bangkok', 'Thailand', 'Central Thailand'),

  ('new-york-city', 'New York City', 'United States', 'New York'),

  ('seoul', 'Seoul', 'South Korea', 'Seoul Capital Area'),

  ('atlanta', 'Atlanta', 'United States', 'Georgia'),

  ('austin', 'Austin', 'United States', 'Texas'),

  ('chicago', 'Chicago', 'United States', 'Illinois')
on conflict (slug) do update
set
  name = excluded.name,
  country = excluded.country,
  region = excluded.region;

-- Replace dish rows each run so photo URLs stay in sync (MVP seed only).
delete from public.dishes;

-- Helper CTE to reference city IDs by slug
with city as (
  select id, slug from public.cities
)
insert into public.dishes (
  city_id,
  name,
  what_it_is,
  ingredients,
  short_history,
  regional_connection,
  is_must_eat,
  is_hidden_gem,
  photo_url,
  photo_source,
  human_validated,
  reviewed_by
)
select
  c.id,
  d.name,
  d.what_it_is,
  d.ingredients,
  d.short_history,
  d.regional_connection,
  d.is_must_eat,
  d.is_hidden_gem,
  d.photo_url,
  d.photo_source,
  d.human_validated,
  d.reviewed_by
from city c
join (
  values
    -- ========== TOKYO: 8 must-eat + 1 hidden gem ==========
    ('tokyo'::text,'Yakitori'::text,'Skewered chicken grilled over charcoal, seasoned with salt or tare.'::text,array['chicken','scallion','tare','salt']::text[],'Skewered chicken took shape in Japan as postwar yatai and small grills fed workers near stations. In Tokyo the format became an izakaya default—salt or tare, parted cuts, and charcoal smoke. Shops clustered around rail hubs and nightlife districts, turning yakitori into the city after-hours language. Today Tokyo still sets the template many izakaya abroad imitate.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Cooking_yakitori.jpg/960px-Cooking_yakitori.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('tokyo'::text,'Shoyu ramen'::text,'Soy-seasoned pork or chicken broth with curly noodles, chashu, and ajitama.'::text,array['noodles','soy','broth','chashu','egg']::text[],'Chinese-style noodle soup met Japanese tastes in the early 20th century and diverged into regional styles. Tokyo shoyu ramen favors a clearer, soy-seasoned broth with curly noodles and restrained toppings. Salaryman neighborhoods and ramen rows in Ikebukuro and elsewhere pushed competition on broth clarity and chashu craft. The capital became a global export hub for that particular bowl.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Shoyu_Ramen_with_Sushi_and_Tempura.jpg/960px-Shoyu_Ramen_with_Sushi_and_Tempura.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('tokyo'::text,'Tsukemen'::text,'Dipping noodles with concentrated broth served separately—often rich and fish-forward.'::text,array['noodles','dashi','pork','fish powder']::text[],'Thick broths and dipping noodles spread as cooks chased richer flavor without soggy noodles. Tokyo shops popularized tsukemen as a Showa-era answer to long queues and heavy soup. East-side ramen battlegrounds still iterate on fish-pork blends and noodle chew. The dish remains identified with capital-level experimentation more than with a single rural hometown.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7f/Tsukemen_%28Dipping_Ramen%29_-_Goemon_Ramen_Bar_2023-06-06.jpg/960px-Tsukemen_%28Dipping_Ramen%29_-_Goemon_Ramen_Bar_2023-06-06.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('tokyo'::text,'Tonkatsu'::text,'Breaded, deep-fried pork cutlet with cabbage, miso soup, and rice.'::text,array['pork','panko','cabbage','rice']::text[],'Breaded cutlets arrived through yōshoku restaurants adapting European frying to Japanese pantries. Tokyo department-store restaurants and old chains normalized tonkatsu sets with shredded cabbage and miso soup. The city framed the dish as everyday comfort rather than special-occasion Western food. Tonkatsu counters remain a benchmark stop for visitors mapping Japanese-style western cuisine.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/Tonkatsu_of_Kimukatsu.jpg/960px-Tonkatsu_of_Kimukatsu.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('tokyo'::text,'Tempura teishoku'::text,'Lightly battered seafood and vegetables fried in sesame oil, served as a set meal.'::text,array['shrimp','fish','vegetables','dipping sauce']::text[],'Edo-period frying began as fast street food; later Ginza-era shops elevated tempura into coursed meals. Tokyo chefs refined oil temperature, batter rhythm, and seasonal seafood for counter seating. Teishoku sets made high-end tempura a lunch and gift-trip ritual. The capital still hosts some of the country''s most famous tempura counters.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6f/Other_stuff...and_shrimp%21.jpg/960px-Other_stuff...and_shrimp%21.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('tokyo'::text,'Gyudon'::text,'Thin-sliced beef simmered with onion over rice—fast, savory, ubiquitous.'::text,array['beef','onion','soy','mirin','rice']::text[],'Simmered beef on rice spread as affordable protein after beef entered the mainstream diet. National chains headquartered in the capital turned gyudon into a commuter default around major stations. Late-night bowls became part of Tokyo rhythm for shift workers and students. The format is now synonymous with fast, filling Kanto counter service.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/Gyuu-don_001.jpg/960px-Gyuu-don_001.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('tokyo'::text,'Unagi kabayaki'::text,'Grilled eel glazed with sweet soy, served over rice in lacquer boxes.'::text,array['eel','soy','sugar','sansho']::text[],'Grilled eel with sweet tare has old river-town roots; Edo developed a strong unagi restaurant culture. Tokyo unagi-ya emphasize knife work, charcoal, and lacquer-box presentation over rice. Summer “doyo no ushi no hi” marketing still spikes city demand. Specialist shops anchor neighborhood maps across the wards.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Unagi_kabayaki_by_Kossy%40FINEDAYS_in_Akabane.jpg/960px-Unagi_kabayaki_by_Kossy%40FINEDAYS_in_Akabane.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('tokyo'::text,'Tamagoyaki'::text,'Layered sweet omelet, often served at sushi bars or in bento.'::text,array['egg','sugar','dashi','soy']::text[],'Layered omelet crossed from home cooking into sushi bars as a benchmark of knife and grill control. Tokyo sushi culture treated tamago as a finishing measure of a chef''s skill. Depachika and markets sell the same slices tourists recognize from omakase counters. The dish signals Edomae discipline as much as breakfast fuel.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/0/06/%E9%B3%A5%E7%84%BC%E3%81%8D%E5%B1%85%E9%85%92%E5%B1%8B_%2839394233682%29.jpg/960px-%E9%B3%A5%E7%84%BC%E3%81%8D%E5%B1%85%E9%85%92%E5%B1%8B_%2839394233682%29.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('tokyo'::text,'Monjayaki'::text,'Runny savory batter on a griddle with cabbage and toppings—Tsukishima classic.'::text,array['flour','dashi','cabbage']::text[],'Kanto working-class cooks stretched flour-batter snacks into a communal griddle dish related to okonomiyaki. Tsukishima street became the spiritual home where cabbage-heavy monja is part theater. Postwar scarcity probably spurred the runnier style. Visitors still treat the neighborhood as the place to try it in Tokyo.'::text,null::text,false::boolean,true::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Monjayaki_dish_from_Tsukishima%2C_Tokyo%2C_Japan%3B_January_2013.jpg/960px-Monjayaki_dish_from_Tsukishima%2C_Tokyo%2C_Japan%3B_January_2013.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    -- ========== PARIS: 8 + 1 ==========
    ('paris'::text,'Steak frites'::text,'Bistro steak with crisp fries, often au poivre or béarnaise.'::text,array['beef','potatoes','butter','pepper']::text[],'Brasserie culture fused French meat cookery with fried potatoes as an affordable plate for urban workers. Paris made steak-frites the weeknight standard you can find in every arrondissement. Cuts and sauces vary, but the pairing stayed a bistro export worldwide. The city still argues over frites crunch and au poivre balance.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Steak-frites_as_served_at_Le_Relais_de_Venise_-_L%27Entrecote.jpg/960px-Steak-frites_as_served_at_Le_Relais_de_Venise_-_L%27Entrecote.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('paris'::text,'Croque-monsieur'::text,'Grilled ham-and-cheese sandwich, often béchamel-topped when “madame” with egg.'::text,array['bread','ham','gruyère','béchamel']::text[],'Café counters needed a hot, quick lunch as Paris office life grew in the early 20th century. The ham-cheese sandwich with optional béchamel became the default; the egg-topped madame variant followed. Boulevard cafés still serve it with a small salad as a textbook Paris lunch. Tourists and locals alike treat it as edible shorthand for café life.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Croque_monsieur_%28French_sandwich%29.jpg/960px-Croque_monsieur_%28French_sandwich%29.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('paris'::text,'French onion soup'::text,'Caramelized onions in rich broth, gratinéed with cheese on bread.'::text,array['onion','beef stock','gruyère','bread']::text[],'Onion soup fortified Les Halles laborers before the market moved; gratinéed bowls turned into bistro comfort. Paris kitchens popularized the cheese lid and beef broth depth tourists expect today. Late-night service kept it on brasserie menus after shifts ended. It is now a global symbol of Paris even when the best bowls are debated block by block.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/45/French_onion_soup_-_Boston%2C_MA.jpg/960px-French_onion_soup_-_Boston%2C_MA.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('paris'::text,'Coq au vin'::text,'Braised chicken in red wine with mushrooms, pearl onion, and lardons.'::text,array['chicken','wine','mushroom','bacon']::text[],'Braised chicken in wine is an old provincial pattern; Burgundy claims part of the lineage. Paris restaurants adopted it as a Sunday bistro dish that could showcase wine and butcher quality. The capital presentation—mushrooms, pearl onions, lardons—became the template travelers know. It remains a bridge between regional terroir and city dining rooms.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/7/75/Coq_au_Vin_6of7_%288735164745%29.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('paris'::text,'Steak tartare'::text,'Hand-chopped raw beef with capers, shallot, egg yolk—served with frites.'::text,array['beef','shallot','capers','mustard']::text[],'Raw chopped beef with capers and egg yolk spread as a bistro test of trust in the butcher. Paris made tartare a benchmark of French beef culture and natural-wine bar menus. Frites on the side nod to brasserie habit. It is less about terroir than about urban confidence in cold-chain quality.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fd/Steak_Tartare_in_Dresden.jpg/960px-Steak_Tartare_in_Dresden.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('paris'::text,'Escargots de Bourgogne'::text,'Snails baked with parsley-garlic butter—classic starter.'::text,array['snail','butter','garlic','parsley']::text[],'Snails in parsley-garlic butter were a Burgundian pattern that brasseries turned into a Paris starter ritual. Escargots became a rite-of-passage dish for visitors learning French table cues. Paris service still emphasizes hot plates, bubbling butter, and bread for sopping. The dish signals classic brasserie more than a single neighborhood.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/9/90/Escargots_%C3%A0_la_bourguignonne_1.jpg/960px-Escargots_%C3%A0_la_bourguignonne_1.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('paris'::text,'Crêpes & galettes'::text,'Thin wheat crêpes sweet or buckwheat galettes savory, from Brittany stalls in Paris.'::text,array['buckwheat','egg','cheese','ham']::text[],'Breton migration brought buckwheat galettes and wheat crêpes to Montparnasse and beyond. Paris crêperies multiplied as affordable evening meals for students and workers. Sweet and savory counters remain a budget-friendly night out. The city is now one of the easiest places to taste Brittany without leaving Île-de-France.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4c/GaletteCidre.JPG/960px-GaletteCidre.JPG'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('paris'::text,'Duck confit'::text,'Salt-cured duck leg slow-cooked in its own fat until melting.'::text,array['duck','salt','garlic','thyme']::text[],'Slow-cooked salt-cured duck is a southwest technique that Paris kitchens refined for bistro plates. Confit traveled along trade routes into city freezers and reheating lines. Paris menus often pair it with lentils or potatoes in the Sarladais style. It represents how regional preservation met metropolitan service.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b1/Duck_confit_-_the_girl_and_the_fig_-_2021-11-10_-_Sarah_Stierch.jpg/960px-Duck_confit_-_the_girl_and_the_fig_-_2021-11-10_-_Sarah_Stierch.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('paris'::text,'Jambon-beurre'::text,'Ham-butter baguette—the city’s fastest iconic lunch.'::text,array['baguette','ham','butter']::text[],'Industrial Paris needed a fast lunch that bakeries could assemble at scale. Thin ham, butter, and baguette became the sandwich default long before trendy fillings. Every serious boulangerie still sells it as a benchmark of bread and ham quality. It is the quiet icon of Paris working lunch.'::text,null::text,false::boolean,true::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/81/Sandwich_jambon-beurre.jpg/960px-Sandwich_jambon-beurre.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    -- ========== MEXICO CITY: 8 + 1 ==========
    ('mexico-city'::text,'Tacos al pastor'::text,'Marinated pork from vertical spit with pineapple, onion, cilantro.'::text,array['pork','tortilla','pineapple','chile']::text[],'Lebanese immigrants brought vertical spit roasting; Mexico adapted it to marinated pork, pineapple, and chile. Mexico City taquerías turned al pastor into the capital late-night identity. Colonias stack competing spits blocks apart. The format is now the city signature taco style worldwide.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/%28El_Flaco%29_Al_Pastor_Tacos.jpg/960px-%28El_Flaco%29_Al_Pastor_Tacos.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('mexico-city'::text,'Carnitas tacos'::text,'Slow-cooked pork shoulder, crisped and chopped onto corn tortillas.'::text,array['pork','tortilla','onion','cilantro']::text[],'Michoacán-style slow pork traveled with migrants and wholesale meat markets. CDMX tortillerías and Sunday cooks scaled carnitas for family meals and taquerías. Crisped edges and salsa variety became capital habits. The dish bridges regional technique with metro-scale supply.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/0/03/Tacos_de_Carnitas_con_nopales.jpg/960px-Tacos_de_Carnitas_con_nopales.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('mexico-city'::text,'Pozole'::text,'Hominy stew with pork or chicken, red or green chile broth, garnished lavishly.'::text,array['hominy','pork','chile','oregano']::text[],'Hominy stew tied to celebration and region; it consolidated as a national party food across Mexico. Mexico City canteens and home kitchens serve red, green, and white versions with lavish garnish. Weekend pozole remains a comfort marker after busy weeks. Independence and family gatherings still call for a pot on the stove.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/1/11/Pozole_Rojo_Mexicano.jpg/960px-Pozole_Rojo_Mexicano.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('mexico-city'::text,'Chiles en nogada'::text,'Poblano stuffed with picadillo, walnut cream, pomegranate—national dish.'::text,array['poblano','meat','walnut','pomegranate']::text[],'Puebla created the walnut-sauced stuffed poblano tied to independence symbolism. Mexico City tables embraced it for September patriotism and fine-dining menus. Flag colors on the plate reinforced national narrative. Seasonal pomegranate availability still shapes when restaurants push it hardest.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Chiles_en_nogada_La_%C3%93pera_CDMX_01.jpg/960px-Chiles_en_nogada_La_%C3%93pera_CDMX_01.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('mexico-city'::text,'Quesadillas de huitlacoche'::text,'Corn fungus quesadillas—earthy, smoky, distinctly central Mexico.'::text,array['tortilla','cheese','huitlacoche']::text[],'Corn smut was an Aztec ingredient that survived in central Mexican cooking. Capital markets and weekend cooks fold huitlacoche into quesadillas for earthy, smoky depth. CDMX is a major stage for mercado-style fillings beyond cheese alone. The dish ties urban eaters to pre-Hispanic flavor.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Quesadilla_de_huitlacoche.jpg/960px-Quesadilla_de_huitlacoche.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('mexico-city'::text,'Tamales'::text,'Masa steamed in corn husks with mole, rajas, or sweet fillings.'::text,array['masa','chile','chicken','lard']::text[],'Steamed masa in husks predates colonization; breakfast street culture amplified tamales in the capital. Vendors with giant ollas became a morning soundtrack across neighborhoods. Fillings range from mole to sweet, reflecting migration into the metro. Tamales remain an affordable, portable taste of home regions.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b8/Tamales_Mexicanos_sweet_corn_tamales_05.jpg/960px-Tamales_Mexicanos_sweet_corn_tamales_05.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('mexico-city'::text,'Elote'::text,'Grilled corn slathered with mayo, cheese, chile, and lime.'::text,array['corn','cotija','lime','chile']::text[],'Grilled corn with mayo, cheese, and chile spread through street fairs and plazas. Mexico City carts made elote and esquites ubiquitous around metro exits and parks. Lime and chile heat balance sweetness for walking snacks. It is street food grammar for CDMX everyday life.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Elote_as%C3%A1ndose.jpg/960px-Elote_as%C3%A1ndose.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('mexico-city'::text,'Mole poblano'::text,'Complex chile-nut-chocolate sauce over turkey or chicken.'::text,array['chile','chocolate','spice','turkey']::text[],'Complex mole from convent kitchens became a feast sauce tied to Puebla and Tlaxcala. City restaurants imported recipes and guarded family variations for holidays. Turkey or chicken under mole anchors celebrations far beyond its origin town. CDMX dining rooms still treat mole as a prestige order.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2f/Mole_Poblano.jpg/960px-Mole_Poblano.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('mexico-city'::text,'Tlacoyos'::text,'Oval masa cakes with beans or fava, salsa and nopales on top.'::text,array['masa','beans','salsa','nopales']::text[],'Oval masa cakes stuffed with beans or fava come from central Mexican antojito tradition. La Merced and other markets showcase tlacoyos as fuel for shoppers and workers. Toppings of salsa and nopales tie the snack to milpa ingredients. They remain a quick taste of street Indigeneity in the capital.'::text,null::text,false::boolean,true::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/82/Tlacoyos_tradicionales.jpg/960px-Tlacoyos_tradicionales.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    -- ========== BANGKOK: 8 + 1 ==========
    ('bangkok'::text,'Pad krapow'::text,'Holy basil stir-fry with meat, chilies, and often a fried egg on rice.'::text,array['basil','garlic','chile','egg']::text[],'Holy basil stir-fry moved from home woks into street stalls as Bangkok grew. Phat kaphrao with a fried egg became the fastest lunch in office zones and transit hubs. Heat level and protein choice vary block by block. The dish is now a national symbol of quick Thai flavor.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Siam_Garden_Phat_kaphrao_ac.jpg/960px-Siam_Garden_Phat_kaphrao_ac.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('bangkok'::text,'Tom yum goong'::text,'Hot-sour shrimp soup with lemongrass, galangal, and lime.'::text,array['shrimp','lemongrass','lime','chile']::text[],'Hot-sour soup with shrimp reflects central Thai herbal balance—lemongrass, galangal, lime. Royal-era recipes later mixed with street pragmatism along riverside restaurants. Bangkok exports tom yum as the global face of Thai soup. Variants noodle the broth for one-bowl meals.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Tom_Yum_Goong_Noodle_Soup_-_Nok_Nok_Kitchen_at_The_Cow_2024-03-28.jpg/960px-Tom_Yum_Goong_Noodle_Soup_-_Nok_Nok_Kitchen_at_The_Cow_2024-03-28.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('bangkok'::text,'Pad Thai'::text,'Stir-fried rice noodles with tamarind, egg, tofu, and peanuts.'::text,array['noodles','tamarind','egg','peanut']::text[],'Stir-fried rice noodles were promoted in the mid-20th century as a national street food project. Bangkok Yaowarat and tourist corridors cemented wok smoke and peanut-tamarind balance as the default taste. Vendors still compete on char and noodle texture. It is deliberately urban Thai identity on a plate.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/3/39/Phat_Thai_kung_Chang_Khien_street_stall.jpg/960px-Phat_Thai_kung_Chang_Khien_street_stall.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('bangkok'::text,'Som tam'::text,'Green papaya salad with lime, fish sauce, peanuts, and chilies.'::text,array['papaya','lime','fish sauce','peanut']::text[],'Isaan mortar salad rode migration into Bangkok labor markets and night markets. Green papaya, lime, and fish sauce became a late-night craving across the capital. Spice levels scale for locals and visitors. Som tam is the most famous Isaan export served in the metropolis.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/6/6c/Som_Tam_green_papaya_salad%2C_Bangkok%2C_Thailand.jpg/960px-Som_Tam_green_papaya_salad%2C_Bangkok%2C_Thailand.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('bangkok'::text,'Boat noodles'::text,'Small bowls of dark pork or beef broth with noodles and offal.'::text,array['noodles','pork','five-spice','blood']::text[],'Canal vendors once served small bowls from boats; Victory Monument later centralized the format on land. Dark five-spice broth and offal toppings define the experience. Queues honor a surviving link to khlong commerce. Bangkok still treats boat noodles as a benchmark street ritual.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7c/Boat_noodles.jpg/960px-Boat_noodles.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('bangkok'::text,'Khao soi'::text,'Curry noodles with crispy egg noodles—northern Thai favorite in Bangkok shops.'::text,array['coconut','noodles','chicken','pickle']::text[],'Curry noodles with crispy noodles are a northern Thai specialty that Bangkok shops adopted for noodle tourists and locals alike. Coconut broth and pickle sides traveled south along migration and media. Trendy cafes now riff on the broth while respecting the Chiang Mai lineage. The capital is the easiest southern hub to find it outside the north.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Trimeresurus_vogeli%2C_Vogel%27s_pit_viper_-_Khao_Soi_Dao_Wildlife_Sanctuary_%2846361404605%29.jpg/960px-Trimeresurus_vogeli%2C_Vogel%27s_pit_viper_-_Khao_Soi_Dao_Wildlife_Sanctuary_%2846361404605%29.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('bangkok'::text,'Mango sticky rice'::text,'Sweet coconut sticky rice with ripe mango—dessert icon.'::text,array['rice','coconut','mango','salt']::text[],'Sweet coconut rice with ripe mango is a seasonal dessert tied to Thai fruit culture. Night markets and Chatuchak lines made it a must-buy for visitors. Salt-kissed coconut cream balances mango perfume. Bangkok stalls turned it into Thailand''s sweetest-known export bite.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Mango_Sticky_Rice_and_Thai_Milk_tea.jpg/960px-Mango_Sticky_Rice_and_Thai_Milk_tea.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('bangkok'::text,'Satay with peanut sauce'::text,'Grilled skewered meat with cucumber relish and peanut dip.'::text,array['chicken','peanut','coconut','cucumber']::text[],'Grilled skewers arrived through Malay and Muslim trade networks around the Gulf. Bangkok night bazaars paired satay with peanut-coconut dip and cucumber relish. Chicken and pork versions compete near riverside tourism. The snack shows how southern flavors met central Thai service styles.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/44/Sate_Ayam_Panggang.jpg/960px-Sate_Ayam_Panggang.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('bangkok'::text,'Khanom buang'::text,'Crisp Thai crepes with sweet or savory toppings.'::text,array['rice flour','egg','coconut']::text[],'Crisp taco-shaped crepes come from old palace-adjacent snack traditions. Fillings split sweet coconut-foyer and savory toppings for temple fairs. Weekend markets keep khanom buang as a walking dessert. Bangkok preserves the format as a heritage sweet beside modern desserts.'::text,null::text,false::boolean,true::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0c/Khanom_bueang_01.jpg/960px-Khanom_bueang_01.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    -- ========== NEW YORK CITY: 8 + 1 ==========
    ('new-york-city'::text,'New York-style pizza slice'::text,'Thin, foldable slice with balanced sauce and cheese.'::text,array['flour','tomato','mozzarella']::text[],'Neapolitan immigrants adapted pizza to coal and gas ovens; slice culture scaled for commuters. Thin, foldable wedges with modest tip grease became the Manhattan default. Dollar-slice economics and borough rivalries shaped how New York eats on the move. The slice is now global shorthand for NYC food.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d5/L%26B_Spumoni_Gardens_pizza_%2841436%29.jpg/960px-L%26B_Spumoni_Gardens_pizza_%2841436%29.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('new-york-city'::text,'Bagel with lox'::text,'Boiled bagel, cream cheese, smoked salmon, capers, onion.'::text,array['bagel','salmon','cream cheese','caper']::text[],'Eastern European bagels met North American smoked fish appetizing culture on the Lower East Side. Cream cheese, capers, and onion layered into a Sunday ritual. Jewish delis made NYC the reference city for the combination. Lines still form at historic counters on weekends.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/c/cb/Lox_Bagel_Sandwich_with_Cream_Cheese_Schmear_Onion_Tomato.jpg/960px-Lox_Bagel_Sandwich_with_Cream_Cheese_Schmear_Onion_Tomato.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('new-york-city'::text,'Pastrami on rye'::text,'Steamed pastrami, mustard, rye bread—deli benchmark.'::text,array['beef','mustard','rye','pickle']::text[],'Romanian and Jewish deli techniques turned spiced brisket into a steamed, hand-carved icon. Katz and peers embedded pastrami in Lower East Side lore. Rye, mustard, and pickle became the canonical frame. Tourists treat the sandwich as edible New York history.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/1/15/Canter%27s_Pastrami_sandwich.jpg/960px-Canter%27s_Pastrami_sandwich.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('new-york-city'::text,'New York cheesecake'::text,'Dense baked cheesecake—often without fruit on top.'::text,array['cream cheese','egg','sugar','crust']::text[],'Jewish-American bakeries developed dense, baked cheesecakes distinct from lighter European styles. Junior and neighborhood bakeries argued over crumb, tang, and height. The slice traveled worldwide as New York dessert branding. It remains a deli and diner benchmark.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/0/09/New_York_cheesecake_2.jpg/960px-New_York_cheesecake_2.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('new-york-city'::text,'Dirty water dog'::text,'Sabrett-style hot dog from a street cart with sauerkraut and onion.'::text,array['beef hot dog','bun','mustard','sauerkraut']::text[],'Street carts boiled Sabrett-style franks in spiced water for Midtown office crowds. Sauerkraut, onion, and mustard became the rushed lunch pattern. Corners still anchor that cart smell in tourist and worker memory. It is pragmatic city fuel more than gourmet ambition.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/3/3d/New_York_hot_dog_stand_%282024%29-L1005645.jpg/960px-New_York_hot_dog_stand_%282024%29-L1005645.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('new-york-city'::text,'Soup dumplings (xiao long bao)'::text,'Steamed pork soup buns—Flushing and Chinatown essential.'::text,array['pork','broth','ginger','wrapper']::text[],'Taiwanese and Shanghai diaspora cooks built dumpling scenes in Flushing and Manhattan Chinatown. Thin skins holding hot broth demand queue patience. Weekend waits map neighborhood food pilgrimage. NYC became North America''s high-visibility hub for the style.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/d/d2/Xiao_Long_Bao_by_Junhao%21.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('new-york-city'::text,'Chicken over rice'::text,'Halal-cart chicken with yellow rice, white sauce, and hot sauce.'::text,array['chicken','rice','yogurt sauce']::text[],'Halal street carts spread yellow rice, yogurt-white sauce, and hot sauce for late-night crowds. Midtown mythology around certain corners amplified the format reputation. It is immigrant entrepreneurship written as a foil-wrapped plate. The dish is now a post-club NYC staple.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/3/32/Chicken_over_rice_%2816425553415%29.jpg/960px-Chicken_over_rice_%2816425553415%29.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('new-york-city'::text,'Bacon-egg-and-cheese'::text,'Breakfast sandwich on a roll—deli/bodega essential.'::text,array['egg','cheese','bacon','roll']::text[],'Bodegas merged breakfast sandwich logic with kaiser or hard rolls for commuters. BEC became hungover shorthand across boroughs. Every neighborhood claims a best version on a roll. It is working-class New York morning culture in wax paper.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/85/Egg_and_cheese_breakfast_sandwich.jpg/960px-Egg_and_cheese_breakfast_sandwich.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('new-york-city'::text,'Bialy'::text,'Chewy onion-poppy roll from Polish-Jewish baking tradition.'::text,array['flour','onion','poppy']::text[],'Polish-Jewish bakers kept the onion-dimpled roll distinct from bagel boiling tradition. Lower East Side ovens preserved a niche beside denser breads. Kossar lineage still anchors how purists define the chew. It is a quieter carb icon next to the bagel.'::text,null::text,false::boolean,true::boolean,'https://upload.wikimedia.org/wikipedia/commons/2/29/Bialy.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    -- ========== SEOUL: 8 + 1 ==========
    ('seoul'::text,'Bibimbap'::text,'Rice bowl with vegetables, gochujang, egg, and often beef.'::text,array['rice','gochujang','spinach','egg']::text[],'Rice bowls topped with namul and gochujang reflect royal presentation simplified for home tables. Seoul restaurants and mall food courts standardized mixed-rice service for speed. Insadong tourism and Korean wave media spread the visual globally. The city remains the easiest place to taste many regional bibimbap spins.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a4/Bibimbap_7.jpg/960px-Bibimbap_7.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('seoul'::text,'Korean BBQ (galbi)'::text,'Marinated short rib grilled at the table with banchan.'::text,array['beef short rib','soy','pear','garlic']::text[],'Tabletop grilling expanded after urban meat supply grew; short-rib marinade with pear and soy became a hallmark. Gangnam and Mapo rooms compete on beef grade and banchan breadth. Seoul exports the all-you-can-eat template abroad. Galbi is the celebratory grill cut many visitors learn first.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/f/fa/Korean_BBQ-Galbi-01.jpg/960px-Korean_BBQ-Galbi-01.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('seoul'::text,'Kimchi jjigae'::text,'Kimchi stew with tofu, pork, and gochugaru heat.'::text,array['kimchi','tofu','pork','gochugaru']::text[],'Aged kimchi stews turned refrigerator culture into bubbling late-night pots. Pojangmacha and 24-hour diners made jjigae the soju companion. Pork, tofu, and rice anchor the heat. Seoul nightlife still runs on shared jjigae after work.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/d/d6/Korean.cuisine-Kimchi_jjigae-01.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('seoul'::text,'Japchae'::text,'Stir-fried glass noodles with vegetables and beef.'::text,array['sweet potato noodle','soy','sesame','spinach']::text[],'Sweet potato noodles stir-fried for palace feasts shrank into party trays and holidays. Seoul homes and caterers treat japchae as a must at gatherings. Sesame and vegetable balance signal festivity. Migration spread the dish, but capital kitchens still set presentation norms.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/9/96/Homemade_Japchae%2C_Dhaka_03.jpg/960px-Homemade_Japchae%2C_Dhaka_03.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('seoul'::text,'Tteokbokki'::text,'Chewy rice cakes in sweet-spicy gochujang sauce.'::text,array['rice cake','gochujang','fish cake','scallion']::text[],'Rice cakes in gochujang sauce jumped from street pojang to mall food courts. Myeongdong cups-to-go made tteokbokki a student snack icon. Fish cake and egg add-ins multiplied over time. Seoul is the epicenter of spicy-chewy rice-cake culture.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/56/Korean.snacks-Tteokbokki-08.jpg/960px-Korean.snacks-Tteokbokki-08.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('seoul'::text,'Sundubu jjigae'::text,'Soft tofu stew with seafood or pork, bubbling in a stone pot.'::text,array['silken tofu','clams','egg','gochugaru']::text[],'Soft tofu stew in a stone bowl took off in restaurant rows during the 1970s and 1980s. Seafood or pork versions anchor drinking districts after midnight. Raw egg cracked tableside finishes many bowls. The capital density of jjigae spots is unmatched nationally.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Korean_stew-Sundubu_jjigae-05.jpg/960px-Korean_stew-Sundubu_jjigae-05.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('seoul'::text,'Samgyeopsal'::text,'Thick-cut pork belly grilled at the table, wrapped in leaves.'::text,array['pork belly','garlic','ssamjang','lettuce']::text[],'Thick pork belly grilled at the table became an affordable all-night protein choice. Lettuce wraps with ssamjang and garlic define the social format. Every neighborhood claims a 24-hour grill room. Seoul turned pork belly into Korean barbecue default for many foreigners.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e1/Korean.cuisine-Samgyeopsal-01.jpg/960px-Korean.cuisine-Samgyeopsal-01.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('seoul'::text,'Korean fried chicken'::text,'Double-fried crisp chicken with sweet-spicy glaze or soy-garlic.'::text,array['chicken','flour','gochujang','garlic']::text[],'Double-frying for shatter and glaze took off after the 1990s franchise boom. Sweet-spicy yangnyeom and soy-garlic variants pair with beer as chimaek culture. Seoul chains and alleys compete on crunch and sauce. The city is the global reference for the style.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Korean_fried_chicken_240206.jpg/960px-Korean_fried_chicken_240206.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('seoul'::text,'Bossam'::text,'Boiled pork belly sliced for wraps with kimchi and ssamjang.'::text,array['pork','cabbage','kimchi']::text[],'Boiled pork belly sliced for wraps descends from celebratory sharing plates. Pojang and specialty houses sell bossam trays for drinking crowds. Kimchi and ssamjang complete the bite. Late-night Seoul still moves bossam when groups want communal protein.'::text,null::text,false::boolean,true::boolean,'https://upload.wikimedia.org/wikipedia/commons/8/8f/Korean_cuisine-Bossam-04.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    -- ========== ATLANTA: 8 + 1 ==========
    ('atlanta'::text,'Lemon pepper wet wings'::text,'Fried wings glazed lemon-pepper “wet” style—city signature.'::text,array['wings','lemon pepper','butter']::text[],'Lemon-pepper seasoning met Buffalo-style wings in strip-mall kitchens across the South. Atlanta clubs and game-day culture pushed “wet” butter-glazed versions as a local flex. Strip malls turned flavor experiments into city identity. Lemon pepper is now a civic wing flavor argument.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Chicken_wings_at_home.jpg/960px-Chicken_wings_at_home.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('atlanta'::text,'Southern fried chicken'::text,'Crispy-skinned chicken with cayenne heat and buttermilk brine.'::text,array['chicken','buttermilk','flour']::text[],'Buttermilk brine and cayenne heat traveled through Georgia Sunday tables and meat-and-threes. Atlanta restaurants debate brine time and dredge mix publicly. Fried chicken anchors soul food and upscale Southern alike. The city sits at a crossroads of national poultry styles.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Fried-Chicken-Set.jpg/960px-Fried-Chicken-Set.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('atlanta'::text,'Peach cobbler'::text,'Baked peaches with biscuit or pie topping—state fruit on a plate.'::text,array['peach','butter','sugar','flour']::text[],'Peach agriculture made cobblers a reunion and church-hall dessert across the state. Atlanta soul-food spots serve warm cobbler to finish meals. Biscuit versus pie topping divides families. It is the state fruit translated into comfort baking.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d0/Fresh_Peach_Cobbler.jpg/960px-Fresh_Peach_Cobbler.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('atlanta'::text,'Pimento cheese'::text,'Sharp cheddar spread with mayo and pimentos—sandwich and cracker star.'::text,array['cheddar','mayo','pimento']::text[],'Sharp cheddar spread with mayo and jarred pimentos became a Southern tea-room staple. Atlanta delis sell tubs for tailgates and sandwiches. The spread bridges crackers, burgers, and fried chicken. It is a portable taste of Upper South hospitality.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Homemade_pimento_cheese_spread_with_crackers.jpg/960px-Homemade_pimento_cheese_spread_with_crackers.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('atlanta'::text,'Biscuits and gravy'::text,'Flaky biscuits with sausage cream gravy.'::text,array['biscuit','sausage','cream','flour']::text[],'Flaky biscuits and sausage cream gravy anchor Southern breakfast diners. Atlanta brunch lines test gravy pepper and biscuit height. Weekend family traffic keeps diners busy. The plate maps Scots-Irish flour culture through Southern pork processing.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/Biscuits_and_sausage_gravy_%288006401964%29.jpg/960px-Biscuits_and_sausage_gravy_%288006401964%29.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('atlanta'::text,'Shrimp and grits'::text,'Lowcountry shrimp over creamy grits with bacon and scallion.'::text,array['shrimp','grits','bacon','stock']::text[],'Lowcountry shrimp met inland grit mills as coastal trade moved up rivers. Atlanta brunch menus reinterpret the dish with bacon and stock. Upscale takes sit beside simpler plates. It shows how Georgia connects coast and capital on one bowl.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Shrimp_and_grits_at_the_Green_Goddess.jpg/960px-Shrimp_and_grits_at_the_Green_Goddess.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('atlanta'::text,'Pulled pork sandwich'::text,'Smoked pork shoulder with vinegar or tomato sauce on a bun.'::text,array['pork shoulder','bun','slaw','sauce']::text[],'Pit-smoked shoulder with slaw reflects Georgia barbecue belt mixing vinegar and tomato-leaning sauces. Atlanta competition BBQ influences neighborhood joints. Sandwiches make the meat portable for festivals. The city debates bark versus sauce balance like any smoke town.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4b/Pulled_pork_sandwich_-_%22Naked%22.jpg/960px-Pulled_pork_sandwich_-_%22Naked%22.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('atlanta'::text,'Sweet tea'::text,'Black tea sweetened while hot—table wine of the South.'::text,array['tea','sugar','water']::text[],'Black tea sweetened while hot became a hospitality default when ice became cheap. Meat-and-threes pour it by the pitcher alongside fried mains. Sugar concentration is a point of pride. Sweet tea is the background beverage of Georgia dining rooms.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/0/08/Southern_Sweet_Tea_%2814888897979%29.jpg/960px-Southern_Sweet_Tea_%2814888897979%29.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('atlanta'::text,'Brunswick stew'::text,'Tomato stew with lima beans, corn, and smoked meat.'::text,array['tomato','pork','corn','lima']::text[],'Hunting-camp pots of tomato, corn, lima beans, and smoked meat drifted across the Southeast with disputed origin stories. Georgia smokehouses simmer overnight batches as a side ritual. Atlanta tables encounter it beside barbecue trays. It is a regional stew that signals gathering and leftovers.'::text,null::text,false::boolean,true::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Brunswick_stew.jpg/960px-Brunswick_stew.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    -- ========== AUSTIN: 8 + 1 ==========
    ('austin'::text,'Breakfast tacos'::text,'Eggs, cheese, and potato on flour or corn tortillas to go.'::text,array['tortilla','egg','cheese','potato']::text[],'Flour and corn tortillas filled with eggs, cheese, and potatoes rode Tex-Mex trailer culture along I-35. Austin morning lines made breakfast tacos the city on-the-go meal. South Lamar and airport-adjacent trailers cemented devotion. The format is now Austin morning identity.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/d/d7/BreakfastTaco.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('austin'::text,'Texas brisket'::text,'Salt-and-pepper smoked brisket with peppery bark.'::text,array['brisket','salt','pepper','post oak']::text[],'Central Texas post-oak smoke and salt-and-pepper bark set a minimalist barbecue standard. Franklin-era queues globalized Austin as a brisket pilgrimage. Slices are judged on smoke ring and tenderness without heavy sauce. Hill Country pits influenced how the city markets smoke.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2d/Smoked_Brisket_with_smoke_ring.jpg/960px-Smoked_Brisket_with_smoke_ring.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('austin'::text,'Beef ribs'::text,'Massive smoked beef ribs with black bark.'::text,array['beef rib','salt','pepper','smoke']::text[],'Massive beef plate ribs showcase patience and bark outside pork-heavy styles. East Austin pits use weekend specials to flex size and smoke time. Beef rib culture overlaps with Central Texas traditions. Visitors compare black bark across competing smokers.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/42/Barbecue_beef_ribs.jpg/960px-Barbecue_beef_ribs.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('austin'::text,'Sausage links'::text,'Pork-and-beef links with jalapeño-cheddar or original spice.'::text,array['pork','beef','jalapeño','smoke']::text[],'Czech and German smokehouse links fused with jalapeño-cheddar and Tex spice along the barbecue belt. Lockhart lineage influences Austin counters through migration and rivalry. Jalapeño links sit beside brisket trays. The city samples Central Texas sausage diversity in one metro.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Sausages_cooking_on_a_barbecue.jpg/960px-Sausages_cooking_on_a_barbecue.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('austin'::text,'Pulled pork'::text,'Shoulder smoked low and sauced light—sandwich or plate.'::text,array['pork shoulder','rub','vinegar']::text[],'East Texas saucier styles meet Hill Country dry rub on shoulder cooks. Food trucks plate pulled pork sliders at festivals with slaw. Vinegar and tomato sauces split preferences by neighborhood. Austin sits between sauce cultures on the Texas map.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e5/Pulled_pork_while_pulling.JPG/960px-Pulled_pork_while_pulling.JPG'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('austin'::text,'Queso fundido'::text,'Melted cheese dip with chiles—Tex-Mex essential.'::text,array['cheese','chile','tomato','cilantro']::text[],'Melted cheese with chiles belongs to border Tex-Mex parlors that patio culture amplified. Austin patios pair queso with margaritas nightly. Chips become the vehicle for communal dipping. Riverside Tex-Mex history still shapes local expectations.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/5/5b/Queso_Flameado_de_Oaxaca.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('austin'::text,'Kolaches'::text,'Czech sweet or sausage-filled pastries—breakfast road-trip fuel.'::text,array['dough','sausage','cheese','jam']::text[],'Czech immigrants baked fruit and sausage kolaches along Central Texas I-35 towns. Austin bakeries merged sweet and savory fillings for commuters. Kolaches function as road-trip breakfast fuel. The city is a southern end of the Czech-Tex pastry trail.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d3/Kol%C3%A1%C4%8Dek.jpg/960px-Kol%C3%A1%C4%8Dek.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('austin'::text,'Banana pudding'::text,'Layered vanilla pudding, bananas, and Nilla wafers—smokehouse dessert.'::text,array['pudding','banana','wafer','cream']::text[],'Layered pudding, bananas, and wafers followed church potlucks and smokehouse dessert menus. Trailers sell cups after brisket trays as a cooling sweet. Nostalgia keeps cups in foil pans. It is the Southern dessert epilogue after smoke.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/d/d2/Banana_foster_bread_pudding_02.jpg/960px-Banana_foster_bread_pudding_02.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('austin'::text,'Frito pie'::text,'Chili and cheese in a Fritos bag—fairground classic.'::text,array['Fritos','chili','cheese','onion']::text[],'Chili and cheese poured into a Fritos bag came from fairgrounds and school concessions. Texas high-school football culture spread the walking format. Rodeo nights still serve the bag as edible nostalgia. Austin festivals keep the crunch-and-chili ritual alive.'::text,null::text,false::boolean,true::boolean,'https://upload.wikimedia.org/wikipedia/commons/e/e5/Frito_Pie_as_Seen_Today.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    -- ========== CHICAGO: 8 + 1 ==========
    ('chicago'::text,'Chicago deep-dish pizza'::text,'Buttery crust, cheese layer, chunky sauce on top.'::text,array['dough','mozzarella','sausage','tomato']::text[],'Mid-century Chicago pizzerias layered cheese, fillings, and chunky sauce in a buttered deep pan for a fork-and-knife meal. Tourists and locals argue whether it beats tavern-cut thin for everyday eating. The style is now a civic trademark alongside New York and Neapolitan narratives. Deep-dish tours anchor food travel itineraries.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/8/80/Deep_Dish_Pizza_PD.jpg/960px-Deep_Dish_Pizza_PD.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('chicago'::text,'Italian beef'::text,'Thin-sliced seasoned beef on a roll with giardiniera or sweet peppers.'::text,array['beef','roll','giardiniera','jus']::text[],'Thin-sliced seasoned beef on a roll with giardiniera or sweet peppers grew from South Side stands serving factory crowds. Dipping the sandwich in jus became a rite; sausage combos layered indulgence. Italian beef is a Chicago sandwich genre more than a generic sub. Locals rank stands by juice and spice bite.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/Buona_Chicago%27s_Original_Italian_Beef.jpg/960px-Buona_Chicago%27s_Original_Italian_Beef.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('chicago'::text,'Chicago hot dog'::text,'All-beef dog with mustard, relish, onion, tomato, pickle, sport pepper, celery salt—no ketchup.'::text,array['beef hot dog','poppy bun','relish','pickle']::text[],'Depression-era stands loaded all-beef dogs with mustard, relish, onion, tomato, pickle, sport pepper, and celery salt—never ketchup. Poppy-seed buns and neon-green relish signal authenticity. Every neighborhood defends a favorite stand. The dog is a designed city icon down to the toppings order.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e6/Chicago-style_Hot_Dog.jpg/960px-Chicago-style_Hot_Dog.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('chicago'::text,'Jibarito'::text,'Smash-fried plantains as “bread” with steak, lettuce, mayo.'::text,array['plantain','steak','cheese','garlic']::text[],'Puerto Rican Chicago cooks swapped bread for fried plantains to build steak sandwiches with lettuce and mayo. Humboldt Park lines trace neighborhood pride in the format. The jibarito is a city invention rarely found elsewhere at scale. It maps Caribbean migration onto midwestern sandwich logic.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/7/7b/Jibarito.jpg/960px-Jibarito.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('chicago'::text,'Maxwell Street Polish'::text,'Grilled Polish sausage with mustard and grilled onion on a roll.'::text,array['pork sausage','mustard','onion','roll']::text[],'Grilled Polish sausage with mustard and onions came from the old Maxwell Street market feeding industrial workers. Late-night windows still sell the smoky link on a roll. It is a South Side craving tied to market memory. The sandwich survived redevelopment through stand loyalty.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Polish_Boy_at_Slyman%27s_Restaurant%2C_2024-08-09%2C_Cleveland%2C_Ohio.jpg/960px-Polish_Boy_at_Slyman%27s_Restaurant%2C_2024-08-09%2C_Cleveland%2C_Ohio.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('chicago'::text,'Tavern-style thin crust'::text,'Crispy square-cut party pizza with fennel sausage.'::text,array['dough','sausage','cheese','tomato']::text[],'Cracker-thin square-cut pizza with fennel sausage spread through South Side taverns as a party-cut alternative to deep dish. Locals often prefer it for weeknight eating over heavier pies. Cheese and sausage ratios differ by bar. It is the everyday Chicago pizza style tourists overlook.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4d/St._Louis-style_pizza_%282%29.jpg/960px-St._Louis-style_pizza_%282%29.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('chicago'::text,'Garrett-style popcorn mix'::text,'Cheese and caramel popcorn blend—sweet-salty stadium snack.'::text,array['popcorn','cheese powder','caramel','butter']::text[],'Cheese and caramel popcorn blends became souvenir tins from State Street shops and airport kiosks. Sweet-salty mixing turned a snack into gift culture. Holiday tins still ship nationwide from Chicago brands. The mix is a modern retail story atop older popcorn street sales.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9b/Caramel_Popcorn_%2832402585090%29.jpg/960px-Caramel_Popcorn_%2832402585090%29.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('chicago'::text,'Italian lemon ice'::text,'Scooped lemon ice—summer sidewalk relief.'::text,array['lemon','sugar','water']::text[],'Italian-American pushcarts scooped lemon ice to cool lakefront summers before air conditioning. Little Italy street festivals keep paper cups of ice as a seasonal ritual. It is a simple immigrant refreshment that survived as festival food. Scoops still signal summer neighborhood fairs.'::text,null::text,true::boolean,false::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/1/10/Glass_cola.jpg/960px-Glass_cola.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text),
    ('chicago'::text,'Malört shot'::text,'Bitter wormwood liqueur—Chicago inside joke and rite of passage.'::text,array['wormwood','spirit','sugar']::text[],'Swedish-style bitter wormwood liqueur was adopted as Chicago bar hazing and pride. Bartenders pour it for initiates and skeptics alike, often with a pickle back. The flavor is divisive by design. Malört is less about taste than about belonging to an in-joke.'::text,null::text,false::boolean,true::boolean,'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a9/Vall%C3%A9rysthal_6_verres_%C3%A0_liqueur_shot_glasses.jpg/960px-Vall%C3%A9rysthal_6_verres_%C3%A0_liqueur_shot_glasses.jpg'::text,'Wikimedia Commons - see file page on commons.wikimedia.org for license and attribution'::text,false::boolean,null::text)
) as d(
  city_slug,
  name,
  what_it_is,
  ingredients,
  short_history,
  regional_connection,
  is_must_eat,
  is_hidden_gem,
  photo_url,
  photo_source,
  human_validated,
  reviewed_by
) on d.city_slug = c.slug;
